#!/usr/bin/env bash
# LOGO DÉFINITIF propagé partout (remplace apply-logo-size.sh et apply-logo-disc.sh) :
#   - public/AKFC_logo.svg : carré, pastille noire intégrée, « KUNG FU CHAMBERY » à écart constant du
#     cercle ; côtés gauche et droit du triangle redessinés en ligne droite, de chaque
#     sommet de la base jusqu'au bord intérieur du cercle extérieur (croisements raccordés) ; sous
#     « KUNG FU CHAMBERY », même écart jusqu'au bord de la pastille qu'entre le texte et le cercle ;
#   - src/app/favicon.ico (16 à 64 px) et public/og-default.png (image de partage) refaits avec ce logo ;
#   - header : logo dans un carré (h = w), ~+25 %, barre de MÊME hauteur ;
#   - accueil : plus de pastille CSS, le logo (à pastille) prend le carré entier.
# Le logo des Réglages : déposer logo-akfc-pastille.svg (site local, puis site en ligne).
# Usage (racine du repo) : bash apply-logo-final.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if grep -q "r=\"382.75\"" "apps/web/public/AKFC_logo.svg" 2>/dev/null; then echo "Déjà appliqué."; exit 0; fi
MODIFIED=("apps/web/src/features/app-shell/Header.tsx" "apps/web/src/app/(public)/page.tsx" "apps/web/public/AKFC_logo.svg" "apps/web/src/app/favicon.ico" "apps/web/public/og-default.png")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
trap 'restore' ERR

mkdir -p "apps/web/public"
base64 -d > "apps/web/public/AKFC_logo.svg" <<'B64'
