python3 - <<'PY'
# Édits par STRUCTURE (et non par texte exact) : marchent sur le code d'origine comme après
# apply-logo-size.sh / apply-logo-disc.sh / une version précédente de ce script.
import re
def edit(path, pattern, repl, n=1, flags=0):
    s = open(path, encoding="utf-8").read()
    found = len(re.findall(pattern, s, flags))
    assert found == n, (path, pattern[:70], found)
    open(path, "w", encoding="utf-8").write(re.sub(pattern, repl, s, flags=flags))
H = "apps/web/src/features/app-shell/Header.tsx"
HC = ("        {/* Trois paliers : le `px-20` d'origine coûtait 160px de chaque\n"
      "            côté, ce que la barre ne pouvait pas se permettre avant 1536px. */}\n"
      "        {/* Logo dans un CARRÉ (largeur = hauteur, object-contain : quel que soit le fichier, il y tient\n"
      "            entier), agrandi SANS grandir la barre : le rembourrage vertical cède exactement ce que le\n"
      "            carré gagne (hauteur de barre inchangée : 92 / 112 / 180 px selon le palier). Le logo carré\n"
      "            à pastille intégrée remplit ce carré. */}\n")
# commentaires + conteneur du logo, entre <Link href="/"> et le <div> (commentaires seuls autorisés entre les deux)
edit(H, r'(<Link href="/">\n)(?:[ \t]*\{/\*.*?\*/\}\n)*[ \t]*<div className="flex items-center px-4 [^"]*">',
     lambda m: m.group(1) + HC + '        <div className="flex items-center px-4 py-2 xl:px-6 xl:py-4 2xl:px-20 2xl:py-[30px]">',
     flags=re.S)
# les deux images du logo (personnalisé + secours)
edit(H, r'className="h-\d+ w-(?:auto|\d+)(?: object-contain)? xl:h-\d+(?: xl:w-\d+)? 2xl:h-\d+(?: 2xl:w-\d+)?"',
     'className="h-19 w-19 object-contain xl:h-20 xl:w-20 2xl:h-30 2xl:w-30"', n=2)
P = "apps/web/src/app/(public)/page.tsx"
PC = ("        {/* La pastille noire fait désormais PARTIE du logo (fichier carré, disque noir sous le dessin\n"
      "            blanc) : logo et pastille grandissent ensemble, à la taille de ce carré. */}\n")
edit(P, r'(<section className="mx-auto max-w-3xl px-4 py-16 text-center">\n)(?:[ \t]*\{/\*.*?\*/\}\n)*[ \t]*<div className="mx-auto mb-6 [^"]*">',
     lambda m: m.group(1) + PC + '        <div className="mx-auto mb-6 h-80 w-80 sm:h-56 sm:w-56 lg:h-80 lg:w-80">',
     flags=re.S)
# images du logo de l'accueil : toute balise <img>/<Image> entre ce conteneur et le titre <h1> remplit le carré
s = open(P, encoding="utf-8").read()
i = s.index('<div className="mx-auto mb-6 h-80 w-80 sm:h-56'); j = s.index("<h1", i)
seg = s[i:j]; tags = re.findall(r'<(?:img|Image)\b[^>]*?/?>', seg, re.S)
assert tags, ("images du logo (accueil) introuvables", seg[:300])
for t in tags:
    t2 = re.sub(r'className=(?:"[^"]*"|\{[^}]*\})', 'className="h-full w-full object-contain"', t, count=1)
    if "className=" not in t: t2 = re.sub(r'^<(img|Image)\b', r'<\1 className="h-full w-full object-contain"', t)
    seg = seg.replace(t, t2, 1)
open(P, "w", encoding="utf-8").write(s[:i] + seg + s[j:])
print("  édits ok (header, accueil ; logo, favicon et image de partage remplacés)")
